class Node { int wartosc; Node next; Node(int w) { wartosc = w; } }

Node odworcListe(Node glowa) {
    Node prev = null, curr = glowa;
    while (curr != null) {
        Node nastepny = curr.next; // ZAPAMIETAJ przed nadpisaniem!
        curr.next = prev;          // odwroc strzalke
        prev = curr;                // przesun prev
        curr = nastepny;            // przesun curr do zapamietanego nastepnika
    }
    return prev; // prev to nowa glowa listy
}

boolean maCykl(Node glowa) {
    Node wolny = glowa, szybki = glowa;
    while (szybki != null && szybki.next != null) {
        wolny = wolny.next;         // 1 krok
        szybki = szybki.next.next;  // 2 kroki
        if (wolny == szybki) return true; // spotkali sie - jest cykl
    }
    return false; // szybki dotarl do konca - brak cyklu
}

Node odworcListe_BLAD(Node glowa) {
    Node prev = null, curr = glowa;
    while (curr != null) {
        curr.next = prev;    // BLAD: nadpisujemy next PRZED zapamietaniem oryginalnego nastepnika!
        prev = curr;
        curr = curr.next;    // to juz WSKAZUJE na prev, nie na oryginalny nastepnik - PETLA UTKNIE
    }
    return prev;
}

Node odworcListe_OK(Node glowa) {
    Node prev = null, curr = glowa;
    while (curr != null) {
        Node nastepny = curr.next; // ZAPAMIETAJ NAJPIERW
        curr.next = prev;
        prev = curr;
        curr = nastepny; // uzywamy ZAPAMIETANEJ wartosci
    }
    return prev;
}
